import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    segments = []
    idx = 1

    for _ in range(n):
        l = int(data[idx])
        r = int(data[idx + 1])
        segments.append((l, r))
        idx += 2

    for i in range(n):
        # Check if segment i covers all other segments
        covers_all = True
        for j in range(n):
            if i == j:
                continue
            # Check if segment i covers segment j
            if not (segments[i][0] <= segments[j][0] and segments[j][1] <= segments[i][1]):
                covers_all = False
                break

        if covers_all:
            print(i + 1)
            return

    print(-1)

if __name__ == "__main__":
    solve()
"}

