import sys

def is_arithmetic_progression(temps):
    """Check if the sequence is an arithmetic progression."""
    if len(temps) <= 2:
        return True  # Any sequence of 2 or fewer terms is trivially an arithmetic progression
    diff = temps[1] - temps[0]
    for i in range(2, len(temps)):
        if temps[i] - temps[i-1] != diff:
            return False
    return True

def predict_temperature(n, temps):
    """Predict the temperature for the (n+1)-th day."""
    if is_arithmetic_progression(temps):
        # Calculate the next term in the arithmetic progression
        diff = temps[1] - temps[0]
        return temps[-1] + diff
    else:
        # The temperature is the same as the last known temperature
        return temps[-1]

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    temps = list(map(int, data[1:n+1]))

    result = predict_temperature(n, temps)
    print(result)

if __name__ == "__main__":
    main()
"}

