def xor_upto(n):
    """Compute XOR from 0 to n"""
    mod = n % 4
    if mod == 0:
        return n
    elif mod == 1:
        return 1
    elif mod == 2:
        return n + 1
    else:  # mod == 3
        return 0

def xor_sequence(start, length):
    """Compute XOR of start, start+1, ..., start+length-1"""
    end = start + length - 1
    return xor_upto(end) ^ xor_upto(start - 1)

