import sys

def solve():
    # Read the four lines
    lines = [line.strip() for line in sys.stdin]

    # Extract descriptions and their lengths
    descriptions = []
    for line in lines:
        # Remove the prefix "X." and get the description
        desc = line[len("X."):]
        descriptions.append(len(desc))

    # Check for great choices
    great_choices = []
    for i in range(4):
        length = descriptions[i]
        other_lengths = descriptions[:i] + descriptions[i+1:]

        # Check if at least twice shorter than all other descriptions
        is_twice_shorter = all(length <= other_length / 2 for other_length in other_lengths)
        # Check if at least twice longer than all other descriptions
        is_twice_longer = all(length >= 2 * other_length for other_length in other_lengths)

        if is_twice_shorter or is_twice_longer:
            great_choices.append(i)

    # Determine the answer
    if len(great_choices) == 1:
        return chr(ord('A') + great_choices[0])
    else:
        return 'C'

if __name__ == "__main__":
    print(solve())
"}

