import math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    # Count of subarrays with each gcd value
    count = {}

    for i in range(n):
        current_gcd = a[i]
        for j in range(i, n):
            current_gcd = math.gcd(current_gcd, a[j])

            if current_gcd == 1:
                break

            count[current_gcd] = count.get(current_gcd, 0) + 1

    q = int(next(it))
    for _ in range(q):
        x = int(next(it))
        print(count.get(x, 0))

if __name__ == "__main__":
    solve()
"}

