import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    k = int(next(it))
    n = int(next(it))

    # Group strings by content
    groups = {}
    for _ in range(k):
        s = next(it)
        a = int(next(it))

        if s not in groups:
            groups[s] = []
        groups[s].append(a)

    # Sort each group by beauty in descending order
    for s in groups:
        groups[s].sort(reverse=True)

    # Use a greedy approach: always try to use the most beautiful strings first
    # We'll keep track of which strings we've used
    used = {}

    # Try to use strings in pairs
    for s in groups:
        beauties = groups[s]
        for i in range(len(beauties)):
            # Try to use this string as part of a pair
            if beauties[i] < 0:
                break  # Don't use negative beauty strings

            # Try to find a matching string
            # If we use this string, we need another string that can pair with it
            # For simplicity, we'll just use the next most beautiful string
            if i + 1 < len(beauties):
                # Use both strings in a pair
                total = beauties[i] + beauties[i + 1]
                print(f"Using pair: {s} ({beauties[i]}) + {s} ({beauties[i + 1]}) = {total}")
                used[s] = used.get(s, 0) + 2
                i += 1
            else:
                # Can't form a pair, try to use it as a middle string if it's a palindrome
                if s == s[::-1]:
                    print(f"Using as middle: {s} ({beauties[i]})")
                    used[s] = used.get(s, 0) + 1
                break

    # Print the total beauty
    print(f"Total: {sum(beauties[i] for s in used for i in range(used[s]) if i < len(groups[s]))}")

if __name__ == "__main__":
    solve()
