def bfs(start, adj, n):
    dist = [-1] * (n + 1)
    queue = [start]
    dist[start] = 0
    while queue:
        u = queue.pop(0)
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

def solve():
    n, k = map(int, input().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        a, b = map(int, input().split())
        adj[a].append(b)
        adj[b].append(a)

    total = 0
    for u in range(1, n + 1):
        dist = bfs(u, adj, n)
        for v in range(1, n + 1):
            if u < v:
                d = dist[v]
                total += (d + k - 1) // k  # ceil(d / k)
    print(total)

