def solve():
    s = input().strip()
    n = len(s)

    # Create a 2D difference array
    diff = [[0] * (n + 2) for _ in range(n + 2)]

    # For each possible starting position i and step size k
    for i in range(n):
        for k in range(1, n - i + 1):
            j = i + k
            if j + k <= n:
                if s[i] == s[j] == s[j + k]:
                    # Mark all intervals [l, r] where l <= i and r >= j + k
                    # This means we want to add 1 to the rectangle (1, j+k) to (i, n)
                    diff[1][j + k] += 1
                    diff[i + 1][j + k] -= 1

                    diff[1][n + 1] -= 1
                    diff[i + 1][n + 1] += 1

    # Compute prefix sums
    for r in range(1, n + 1):
        for c in range(1, n + 1):
            diff[r][c] += diff[r][c - 1]

    for c in range(1, n + 1):
        for r in range(1, n + 1):
            diff[r][c] += diff[r - 1][c]

    # The answer is the number of marked intervals
    ans = 0
    for r in range(1, n + 1):
        for c in range(1, n + 1):
            ans += diff[r][c]

    print(ans)

