def find_joyful_t(n, crush):
    """Find the smallest t such that for each person x, if x starts some round and y becomes the Joon-Joon,
    then by starting from y, x would become the Joon-Joon of the round."""

    visited = [False] * n
    cycles = []

    for i in range(n):
        if not visited[i]:
            cycle = []
            j = i
            while not visited[j]:
                visited[j] = True
                cycle.append(j)
                j = crush[j] - 1  # convert to 0-indexed
            cycles.append(cycle)

    # Check if it's possible
    lcm_value = 1
    for cycle in cycles:
        L = len(cycle)
        # Calculate L/gcd(2, L)
        if L % 2 == 0:
            # L is even, need L/2
            lcm_value = lcm(lcm_value, L // 2)
        else:
            # L is odd, need L
            lcm_value = lcm(lcm_value, L)

    return lcm_value

