def find_min_t(n, crush):
    # Find cycles in the graph
    visited = [False] * (n + 1)
    cycle_lengths = []

    for i in range(1, n + 1):
        if not visited[i]:
            current = i
            cycle = []
            while not visited[current]:
                visited[current] = True
                cycle.append(current)
                current = crush[current - 1]  # crush is 0-indexed in list, people are 1-indexed

            # The cycle length is the number of people in the cycle
            cycle_length = len(cycle)
            cycle_lengths.append(cycle_length)

    # Calculate LCM of all cycle lengths
    from math import gcd

    def lcm(a, b):
        return a * b // gcd(a, b)

    order = cycle_lengths[0]
    for length in cycle_lengths[1:]:
        order = lcm(order, length)

    # We need 2t to be a multiple of order, so t = order / 2 rounded up if order is odd
    if order % 2 == 0:
        return order // 2
    else:
        return -1

