import sys
import math

def is_prime(n):
    """Check if n is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
        if n % i == 0:
            return False
        i += 2
    return True

def solve():
    q = int(sys.stdin.readline())

    if q <= 2:
        print(1)
        print(0)
        return

    if is_prime(q):
        print(1)
        print(0)
        return

    # Check if any non-trivial divisor leads to a losing position
    # A losing position is a number with no non-trivial divisors (prime or 1)
    # But we need to check if all non-trivial divisors are winning

    # Check if q has a non-trivial divisor that is prime
    for i in range(2, int(math.isqrt(q)) + 1):
        if q % i == 0:
            # i is a non-trivial divisor
            if is_prime(i):
                # Move to a prime (winning for opponent)
                continue
            else:
                # Move to a composite
                # We need to check if this composite is losing
                # A composite is losing if all its non-trivial divisors are primes
                # Check if i has any non-trivial divisors other than primes
                has_non_prime_divisor = False
                for j in range(2, int(math.isqrt(i)) + 1):
                    if i % j == 0:
                        if not is_prime(j):
                            has_non_prime_divisor = True
                            break
                if not has_non_prime_divisor:
                    # i is losing
                    print(1)
                    print(i)
                    return

    # If we reach here, all non-trivial divisors are primes
    print(2)

if __name__ == "__main__":
    solve()
"}

