    # If x == 0, no pictures can be reposted
    if x == 0:
        print(-1)
        return

    # DP table: dp[i][j] = max sum when considering first i pictures and selecting j pictures
    dp = [[-1] * (x + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, x + 1):
            # Option 1: don't select picture i
            if dp[i-1][j] != -1:
                dp[i][j] = dp[i-1][j]

            # Option 2: select picture i
            # Previous selection must be within the last k-1 positions
            start = max(0, i - k)
            for m in range(start, i):
