def count_good_intervals(s):
    n = len(s)

    # Find all good triples
    good_triples = []
    for x in range(n):
        for k in range(1, n - x):
            if x + 2 * k < n:
                if s[x] == s[x + k] == s[x + 2 * k]:
                    good_triples.append((x, x + k, x + 2 * k))

    # Count intervals that contain at least one good triple
    # Use a 2D difference array approach
    diff = [[0] * (n + 2) for _ in range(n + 2)]

    for triple in good_triples:
        x, xk, x2k = triple
        lmin = 1
        lmax = x + 1  # intervals are [l, r], so we need to check l <= x
        rmin = x2k
        rmax = n

        # Mark the rectangle [lmin, lmax] x [rmin, rmax]
        diff[lmin][rmin] += 1
        diff[lmax + 1][rmin] -= 1
        diff[lmin][rmax + 1] -= 1
        diff[lmax + 1][rmax + 1] += 1

    # Compute 2D prefix sum
    for i in range(n + 1):
        for j in range(n + 1):
            if i > 0:
                diff[i][j] += diff[i - 1][j]
            if j > 0:
                diff[i][j] += diff[i][j - 1]
            if i > 0 and j > 0:
                diff[i][j] -= diff[i - 1][j - 1]

    # Count intervals with at least one good triple
    total = 0
    for l in range(n):
        for r in range(n):
            if diff[l + 1][r + 1] > 0:
                total += 1

    return total

