import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data.pop(0))
    a = list(map(int, data[:n]))
    b = list(map(int, data[n:]))

    # Find positions of each value in a and b
    a_map = {}
    b_map = {}

    for i in range(n):
        a_map[a[i]] = i
        b_map[b[i]] = i

    # For each value, get all indices where it appears
    counts = {}
    positions_a = {}
    positions_b = {}

    seen = set()
    for i in range(n):
        val_a = a[i]
        val_b = b[i]

        if val_a not in seen:
            counts[val_a] = counts.get(val_a, 0) + 1
            seen.add(val_a)
            positions_a[val_a] = [val_b]
        else:
            seen.remove(val_a)
            seen.add(val_b)
            counts[val_b] = counts.get(val_b, 0) + 1
            seen.add(val_b)

    answer = 0
    try:
        for v in seen:
            count_a = counts[v] if v in a_map else 0
            count_b = counts[v] if v in b_map else 0
            if count_a > 0 and count_b > 0:
                match_count = min(count_a, count_b)
                answer += match_count
    except KeyError:
        answer = 0

    print(answer)

if __name__ == "__main__":
    solve()
"}

