import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # If first day has 0 teams, we can't start a coupon
    if a[0] == 0:
        if a[0] % 2 != 0:
            print("NO")
            return

    # Process each day
    for i in range(n):
        # If we need an odd number of pizzas, we need to start a coupon
        if a[i] % 2 == 1:
            # Need a coupon that starts on this day
            if i == n - 1:
                # Can't start a coupon on the last day
                print("NO")
                return
            if a[i+1] < 1:
                # Not enough pizzas on the next day for the coupon
                print("NO")
                return

            # Use 1 pizza from this day and 1 from the next day
            a[i] -= 1
            a[i+1] -= 1

        # Use discount 1 for the remaining pizzas
        if a[i] % 2 == 0:
            a[i] //= 2

    print("YES")

if __name__ == "__main__":
    solve()
