def count_pairs(s):
    mod = 10**9 + 7
    result = 1

    for char in s:
        # Convert character to its base-64 value
        if '0' <= char <= '9':
            val = int(char)
        elif 'A' <= char <= 'Z':
            val = 10 + ord(char) - ord('A')
        elif 'a' <= char <= 'z':
            val = 36 + ord(char) - ord('a')
        elif char == '-':
            val = 62
        elif char == '_':
            val = 63
        else:
            raise ValueError(f"Invalid character: {char}")

        # Count pairs (a, b) such that a & b = val
        # For each bit, if val's bit is 1, both a and b must have that bit as 1
        # If val's bit is 0, at least one of a or b must have that bit as 0

        # Number of valid pairs for this character
        count = 1
        for i in range(6):
            if (val >> i) & 1:
                # Bit is 1 in val
                # Both a and b must have this bit as 1
                # 1 possibility
                pass
            else:
                # Bit is 0 in val
                # (a bit 0, b bit 0), (a bit 0, b bit 1), (a bit 1, b bit 0)
                count *= 3

        result = (result * count) % mod

    return result

s = input().strip()
print(count_pairs(s))
