import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    q = int(next(it))
    queries = [int(next(it)) for _ in range(q)]

    # Count occurrences of each GCD
    from collections import defaultdict
    count = defaultdict(int)

    # For each position, track GCDs of subarrays ending at that position
    prev_gcds = {}

    for num in a:
        curr_gcds = {}
        # Extend subarrays from previous position
        for g in prev_gcds:
            new_gcd = gcd(g, num)
            curr_gcds[new_gcd] = curr_gcds.get(new_gcd, 0) + prev_gcds[g]
        # Add subarray consisting of just the current number
        curr_gcds[num] = curr_gcds.get(num, 0) + 1

        # Update overall count
        for g, c in curr_gcds.items():
            count[g] += c

        prev_gcds = curr_gcds

    # Process queries
    for x in queries:
        print(count.get(x, 0))

# Helper function for GCD
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

if __name__ == "__main__":
    solve()
