    # Check if all words are valid
    for word in words:
        part, gender = classify_word(word)
        if part is None or gender is None:
            print("NO")
            return

    # Check if it's a single word
    if len(words) == 1:
        print("YES")
        return

    # Check if it's a valid statement
    # Get part of speech and gender for each word
    parts = []
    genders = []
    for word in words:
