        parts.append(part)
        genders.append(gender)

    # Check gender consistency
    if len(set(genders)) != 1:
        print("NO")
        return

    # Check part of speech order: adjectives (0+) + noun (1) + verbs (0+)
    # Find the position of the noun
    noun_pos = -1
    for i, part in enumerate(parts):
        if part == "noun":
            noun_pos = i
            break

    if noun_pos == -1:
