import sys
from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Build adjacency list
    adj = defaultdict(set)
    idx = 2
    for _ in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        adj[u].add(v)
        adj[v].add(u)
        idx += 2

    # Find connected components
    visited = set()
    for node in range(1, n + 1):
        if node not in visited:
            # BFS to find component
            component = set()
            queue = deque([node])
            visited.add(node)
            while queue:
                curr = queue.popleft()
                component.add(curr)
                for neighbor in adj[curr]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)

            # Check if component is a clique
            is_clique = True
            for u in component:
                for v in component:
                    if u != v and v not in adj[u]:
                        is_clique = False
                        break
                if not is_clique:
                    break

            if not is_clique:
                print("NO")
                return

    print("YES")

if __name__ == "__main__":
