import sys

def max_regular_bracket_sequence(s):
    """Find the maximum length of a regular bracket sequence."""
    # Count opening parentheses from left to right
    left_count = 0
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
            left_count += 1
        else:
            balance -= 1
        # If balance is negative, we've seen an unmatched closing parenthesis
        if balance < 0:
            balance = 0

    # Count opening parentheses from right to left
    right_count = 0
    balance = 0
    for char in reversed(s):
        if char == '(':
            balance += 1
            right_count += 1
        else:
            balance -= 1
        # If balance is negative, we've seen an unmatched opening parenthesis
        if balance < 0:
            balance = 0

    return 2 * min(left_count, right_count)

def main():
    s = sys.stdin.readline().strip()
    print(max_regular_bracket_sequence(s))

if __name__ == "__main__":
    main()
