def is_arithmetic_progression(seq):
    """Check if the sequence is an arithmetic progression."""
    if len(seq) <= 2:
        return True  # Any sequence with 2 or fewer elements is trivially an arithmetic progression
    d = seq[1] - seq[0]
    for i in range(2, len(seq)):
        if seq[i] - seq[i-1] != d:
            return False
    return True

