import math

def find_kth_divisor(n, k):
    """Find the k-th smallest divisor of n"""
    divisors = set()

    # Find all divisors
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)

    # Convert to sorted list
    divisors = sorted(divisors)

    # Check if k-th divisor exists
    if k > len(divisors):
        return -1

    return divisors[k - 1]

