import sys

def is_arithmetic_progression(temps):
    """Check if the sequence forms an arithmetic progression"""
    if len(temps) <= 2:
        return True  # Any sequence with 2 or fewer elements is trivially an AP
    diff = temps[1] - temps[0]
    for i in range(2, len(temps)):
        if temps[i] - temps[i-1] != diff:
            return False
    return True

def predict_temperature(n, temps):
    """Predict the temperature for the (n+1)-th day"""
    if is_arithmetic_progression(temps):
        # Calculate the next term in the arithmetic progression
        common_diff = temps[1] - temps[0]
        return temps[-1] + common_diff
    else:
        # Return the last known temperature
        return temps[-1]

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    temps = list(map(int, data[1:1+n]))

    result = predict_temperature(n, temps)
    print(result)

if __name__ == "__main__":
    main()
