import sys

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    # If there's only one lamp, no changes needed
    if n == 1:
        print(0)
        print(s)
        return

    # Start with the first lamp
    prev_color = s[0]
    result = [prev_color]
    changes = 0

    for i in range(1, n):
        current_color = s[i]

        # If current color is different from previous, keep it
        if current_color != prev_color:
            result.append(current_color)
            prev_color = current_color
        else:
            # Current color is the same as previous, need to change
            # Try both other colors
            option1 = None
            option2 = None

            # Find the two colors that are different from current_color
            for c in ['R', 'G', 'B']:
                if c != current_color:
                    if option1 is None:
                        option1 = c
                    else:
                        option2 = c

            # Count occurrences of each color in the remaining string
            count = {}
            for c in ['R', 'G', 'B']:
                count[c] = 0

            for j in range(i, n):
                count[s[j]] += 1

            # Choose the color that appears least in the remaining string
            # This minimizes the number of changes needed later
            if count[option1] <= count[option2]:
                chosen = option1
            else:
                chosen = option2

            result.append(chosen)
            changes += 1
            prev_color = chosen

    print(changes)
    print(''.join(result))

if __name__ == "__main__":
    solve()
