import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    x = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Special case: k == 1
    if k == 1:
        if x == n:
            print(sum(a))
        else:
            print(-1)
        return

    # Special case: k > n
    if k > n:
        print(-1)
        return

    # DP: dp[i][j] = maximum sum when considering first i pictures, selecting j pictures,
    # and the last selected picture is at position i
    dp = [[-1] * (x + 1) for _ in range(n + 1)]

    # Base case: select the first picture
    for i in range(1, min(k, n) + 1):
        dp[i][1] = a[i-1]

    # Fill DP table
    for i in range(2, n + 1):
        for j in range(2, x + 1):
            # We select picture i, so we look back to positions i-k to i-1
            for m in range(i - k, i):
                if m >= 1 and dp[m][j-1] != -1:
                    dp[i][j] = max(dp[i][j], dp[m][j-1] + a[i-1])

    # Check if we can select x pictures ending at position n
    result = -1
    for i in range(max(x, k), n + 1):
        if dp[i][x] != -1:
            result = max(result, dp[i][x])

    print(result)

if __name__ == "__main__":
    solve()
