    # Calculate floor values
    b = []
    for num in a:
        if num.is_integer():
            b.append(int(num))
        else:
            b.append(int(num))  # floor

    # Calculate sum of b
    sum_b = sum(b)

    # If sum is already 0, we're done
    if sum_b == 0:
        for val in b:
            print(val)
        return

    # We need to convert (0 - sum_b) numbers from floor to ceil
    needed = 0 - sum_b

    # Convert needed numbers from floor to ceil
    # We'll just pick the first needed non-integer numbers
    for i in range(n):
        if not a[i].is_integer():
            if needed > 0:
                b[i] = int(a[i] + 1e-9)  # ceil
                needed -= 1
            else:
                break

    for val in b:
        print(val)

