def can_construct(s, t):
    """Check if t can be constructed from s."""
    # Check if all characters in t are in s
    if not set(t).issubset(set(s)):
        return False

    # Check if t can be constructed greedily
    pos = 0
    while pos < len(t):
        found = False
        # Try all possible lengths from longest to shortest
        for l in range(len(t) - pos, 0, -1):
            # Try all possible substrings of s
            for i in range(len(s) - l + 1):
                s_sub = s[i:i+l]
                # Check if this substring matches t[pos:pos+l] directly or reversed
                if s_sub == t[pos:pos+l] or s_sub == t[pos:pos+l][::-1]:
                    # Found a match
                    found = True
                    break
            if found:
                break
        if not found:
            return False
        pos += l
    return True

# Main program
s = input().strip()
t = input().strip()

if not can_construct(s, t):
    print(-1)
else:
    # Find the actual solution
    pos = 0
    result = []
    while pos < len(t):
        # Try all possible lengths from longest to shortest
        for l in range(len(t) - pos, 0, -1):
            # Try all possible substrings of s
            for i in range(len(s) - l + 1):
                s_sub = s[i:i+l]
                # Check if this substring matches t[pos:pos+l] directly or reversed
                if s_sub == t[pos:pos+l] or s_sub == t[pos:pos+l][::-1]:
                    # Found a match
                    # Calculate the end position in t
                    end_pos = pos + l
                    # Calculate the start and end positions in s
                    start_s = i
                    end_s = i + l
                    # Add to result
                    if start_s <= end_s:
                        result.append((start_s + 1, end_s + 1))  # 1-indexed
                    else:
                        result.append((end_s + 1, start_s + 1))  # Reversed
                    pos = end_pos
                    break

    print(len(result))
    for x, y in result:
        print(x, y)
