def find_karen_house(n, k):
    """Find the house Karen will move into."""

    # Base cases
    if k == 1:
        return 1
    if k == 2:
        return n
    if k == 3:
        return (n + 1) // 2
    if k == 4:
        return 2
    if k == 5:
        return (n + 3) // 2
    if k == 6:
        return (n + 5) // 2
    if k == 7:
        return n - 1

    return (n + (2 * k - 3)) // 2

