import sys

def classify_word(word):
    """Classify a word by part of speech and gender"""
    if word.endswith("lios"):
        return "adjective", "masculine"
    elif word.endswith("liala"):
        return "adjective", "feminine"
    elif word.endswith("etr"):
        return "noun", "masculine"
    elif word.endswith("etra"):
        return "noun", "feminine"
    elif word.endswith("initis"):
        return "verb", "masculine"
    elif word.endswith("inites"):
        return "verb", "feminine"
    else:
        return None, None  # Invalid word

def solve():
    words = sys.stdin.read().strip().split()

    # Classify all words
    classifications = []
    for word in words:
        part_of_speech, gender = classify_word(word)
        if part_of_speech is None:
            print("NO")
            return
        classifications.append((part_of_speech, gender))

    # Check if all words have the same gender
    gender = classifications[0][1]
    for part_of_speech, g in classifications:
        if g != gender:
            print("NO")
            return

    # Check if it's a valid statement or single word
    if len(classifications) == 1:
        print("YES")
        return

    # Check order: adjectives (0+), noun (1), verbs (0+)
    adjective_count = 0
    noun_count = 0
    verb_count = 0

    for part_of_speech, _ in classifications:
        if part_of_speech == "adjective":
            adjective_count += 1
        elif part_of_speech == "noun":
            noun_count += 1
        elif part_of_speech == "verb":
            verb_count += 1

    # Check order: adjectives first, then noun, then verbs
    if noun_count == 0 or noun_count > 1:
        print("NO")
        return

    if adjective_count > 0 and noun_count > 0 and verb_count > 0:
        # Check if adjectives come before noun and verbs come after noun
        # We need to verify the order in the sequence
        noun_position = -1
        for i, (part_of_speech, _) in enumerate(classifications):
            if part_of_speech == "noun":
                noun_position = i
                break

        # All adjectives should be before the noun
        for i in range(noun_position):
            if classifications[i][0] != "adjective":
                print("NO")
                return

        # All verbs should be after the noun
        for i in range(noun_position + 1, len(classifications)):
            if classifications[i][0] != "verb":
                print("NO")
                return

    print("YES")

if __name__ == "__main__":
    solve()
