    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)

    total = 0

    # For each vertex, perform BFS to find distances to all other vertices
    for start in range(1, n + 1):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)

        # Add to total
        for t in range(1, n + 1):
