    # If s * 2 > e, starting player must add 1
    # This leads to s + 1
    if s * 2 > e:
        # Next player's turn with s + 1
        # If s + 1 == e, next player can't move and loses
        if s + 1 == e:
            return True
        elif s + 1 < e:
            # If both moves are losing for next player, starting player wins
            if 2 * (s + 1) > e and (s + 1) + 1 > e:
