def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))
        x = [int(next(data)) for _ in range(n)]

        # Precompute bit counts
        cnt = [0] * 60
        for num in x:
            for b in range(60):
                if num & (1 << b):
                    cnt[b] += 1

        result = 0
        for j in range(n):
            # Compute sum_and = sum(x_i & x_j) for all i
            sum_and = 0
            for b in range(60):
                if x[j] & (1 << b):
                    sum_and += cnt[b] * (1 << b)

            # Compute sum_or = sum(x_j | x_k) for all k
            sum_or = 0
            for b in range(60):
                if x[j] & (1 << b):
                    # bit b set in x_j, so all n numbers contribute bit b
                    sum_or += n * (1 << b)
                else:
                    # bit b not set in x_j, so only cnt[b] numbers contribute bit b
                    sum_or += cnt[b] * (1 << b)

            result += sum_and * sum_or
            result %= MOD

        print(result)

