def find_cycles(n, crush):
    visited = [False] * (n + 1)
    cycles = []

    for i in range(1, n + 1):
        if not visited[i]:
            cycle = []
            j = i
            while not visited[j]:
                visited[j] = True
                cycle.append(j)
                j = crush[j - 1]  # crush is 0-indexed, people are 1-indexed
            cycles.append(len(cycle))

    # Check if all cycles have the same required t
    required_t = None
    for L in cycles:
        if L == 1:
            # Self-loop: always works with t=1
            if required_t is None:
                required_t = 1
            elif required_t != 1:
                return -1
        elif L % 2 == 1:
            # Odd cycle: requires t = L
            if required_t is None:
                required_t = L
            elif required_t != L:
                return -1
        else:
            # Even cycle: requires t = L / 2
            t = L // 2
            if required_t is None:
                required_t = t
            elif required_t != t:
                return -1

    return required_t

def main():
    n = int(input())
    crush = list(map(int, input().split()))

    result = find_cycles(n, crush)
    print(result)

if __name__ == "__main__":
    main()
