        if L == 1:
            # Self-loop: always works with t=1
            if required_t is None:
                required_t = 1
            elif required_t != 1:
                return -1
        elif L % 2 == 1:
            # Odd cycle: requires t = L
            if required_t is None:
                required_t = L
            elif required_t != L:
                return -1
        else:
            # Even cycle: requires t = L / 2
            t = L // 2
            if required_t is None:
                required_t = t
            elif required_t != t:
                return -1

    return required_t

def main():
