import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    x = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Edge cases
    if k == 1:
        if x != n:
            print(-1)
            return
        # If k == 1 and x == n, we can just sum all beauties
        print(sum(a))
        return

    if k > n:
        print(-1)
        return

    # DP[i][j]: max sum by considering first i pictures, selecting j pictures
    INF = -1
    DP = [[INF] * (x + 1) for _ in range(n + 1)]
    DP[0][0] = 0

    for i in range(1, n + 1):
        for j in range(x + 1):
            # Select the i-th picture
            if j > 0:
                DP[i][j] = max(DP[i][j], DP[i-1][j-1] + a[i-1])

            # Don't select the i-th picture
            # We need to ensure that we have selected at least one picture in the last k-1 positions
            if DP[i-1][j] != INF:
                # Check if we have selected at least one picture in the last k-1 positions
                has_selected = False
                for l in range(1, min(k, i) + 1):
                    if DP[i-l][j] != INF:
                        has_selected = True
                        break
                if has_selected:
                    DP[i][j] = max(DP[i][j], DP[i-1][j])

    result = DP[n][x]
    if result == INF:
        print(-1)
    else:
        print(result)

if __name__ == "__main__":
    solve()
