def find_karen_house(n, k):
    """Simulate the placement of people to find Karen's house."""

    occupied = []

    # Place the first k-1 people greedily
    for i in range(k - 1):
        # Find the position that maximizes the minimum distance to any occupied house
        best_pos = -1
        max_dist = -1

        for pos in range(1, n + 1):
            if pos not in occupied:
