                min_dist = min(abs(pos - occ) for occ in occupied) if occupied else float('inf')

                if min_dist > max_dist or (min_dist == max_dist and pos < best_pos):
                    best_pos = pos
                    max_dist = min_dist

        occupied.append(best_pos)

    # The k-th person is the last one placed
    return occupied[-1]

def main():
    n, k = map(int, input().split())
    print(find_karen_house(n, k))

