def is_winning(q, memo):
    """Check if q is a winning position."""
    if q < 4:
        return False  # Losing position

    if q in memo:
        return memo[q]

    # Find all non-trivial divisors of q
    divisors = set()
    for i in range(2, int(q**0.5) + 1):
        if q % i == 0:
            if i != q:
                divisors.add(i)
            if q // i != q and q // i != 1:
                divisors.add(q // i)

    # Check if all divisors are winning positions
    all_winning = True
    for d in divisors:
        if not is_winning(d, memo):
            all_winning = False
            break

    memo[q] = not all_winning  # Winning if at least one divisor is losing
    return memo[q]

def solve(q):
    """Solve the game for a given q."""
    memo = {}

    if q < 4:
        print(1)
        print(0)
