            if answer == 'Y':
                # y >= x
                lower = x
            else:
                # y < x
                upper = x - 1
        elif sign == '<=':
            if answer == 'Y':
                # y <= x
                upper = x
            else:
                # y > x
                lower = x + 1

    if lower > upper:
        print("Impossible")
