def bfs_distances(tree, start):
    n = len(tree)
    distances = [float('inf')] * n
    distances[start] = 0
    queue = [start]
    while queue:
        u = queue.pop(0)
        for v in tree[u]:
            if distances[v] == float('inf'):
                distances[v] = distances[u] + 1
                queue.append(v)
    return distances

