    n, k = map(int, input().split())
    tree = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v = map(int, input().split())
        tree[u - 1].append(v - 1)
        tree[v - 1].append(u - 1)

    total = 0
    for start in range(n):
        distances = bfs_distances(tree, start)
        for end in range(n):
            if start < end:
                d = distances[end]
                jumps = (d + k - 1) // k  # ceil division
                total += jumps
    print(total)

