    b = []
    for num in integers:
        b.append(int(num))

    for num in non_integers:
        b.append(int(num))

    # Calculate the current sum
    current_sum = sum(b)

    # We need the sum to be 0, so we need to adjust
    # For each non-integer, we can choose to round up or down
    # The difference between rounding up and down is:
    # If we round down, we have error = fractional part
    # If we round up, we have error = 1 - fractional part

    # Let's try to adjust by rounding up for non-integers
    for i, num in enumerate(non_integers):
        if current_sum > 0:
            # Need to decrease the sum
            if num % 1 > 0.5:
                # Rounding up decreases the sum more
