import sys

def is_great(length, other_lengths):
    """Check if a choice with given length is great"""
    # Check if at least twice shorter than all others
    if all(length <= other_length / 2 for other_length in other_lengths):
        return True

    # Check if at least twice longer than all others
    if all(length >= 2 * other_length for other_length in other_lengths):
        return True

    return False

def solve():
    # Read the four lines
    lines = [sys.stdin.readline().strip() for _ in range(4)]

    # Extract lengths
    lengths = []
    for line in lines:
        # Remove the prefix "X." and get the length
        desc = line[len(line) - len(line) + 1:]  # Remove "X." prefix
        lengths.append(len(desc))

    # Check for great choices
    great_choices = []
    for i, length in enumerate(lengths):
        other_lengths = lengths[:i] + lengths[i+1:]
        if is_great(length, other_lengths):
            great_choices.append(i)

    # Determine the answer
    if len(great_choices) == 1:
        return chr(ord('A') + great_choices[0])
    else:
        return 'C'

if __name__ == "__main__":
    print(solve())
