def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    q = int(next(it))
    queries = [int(next(it)) for _ in range(q)]

    # Dictionary to count occurrences of each gcd value
    count = {}

    # For each starting index l
    for l in range(n):
        # Dictionary to track gcd values for subarrays starting at l
        curr_gcd = {}

        # Extend to the right from l
        for r in range(l, n):
            # Compute gcd of a[l..r]
            if l == r:
                gcd_val = a[r]
            else:
                gcd_val = curr_gcd.get(a[r], a[r])

            # Update current gcd values
            new_gcd = {}
            for key, val in curr_gcd.items():
                new_gcd[gcd(key, val)] = val
            new_gcd[gcd_val] = new_gcd.get(gcd_val, 0) + 1
            curr_gcd = new_gcd

            # Update the overall count
            count[gcd_val] = count.get(gcd_val, 0) + 1

    # Process queries
    for x in queries:
        print(count.get(x, 0))

