def solve():
    n = int(input())
    s = input().strip()

    # DP table: dp[i][c] = minimum changes to make first i lamps diverse, with i-th lamp color c
    # c can be 'R', 'G', 'B'
    dp = [[float('inf')] * 3 for _ in range(n)]

    # Initialize first lamp
    for i, c in enumerate(['R', 'G', 'B']):
        if s[0] == c:
            dp[0][i] = 0
        else:
            dp[0][i] = 1

    # Fill DP table
    for i in range(1, n):
        for curr_color_idx, curr_color in enumerate(['R', 'G', 'B']):
            # Previous color must be different
            for prev_color_idx, prev_color in enumerate(['R', 'G', 'B']):
                if prev_color != curr_color:
                    if s[i] == curr_color:
                        dp[i][curr_color_idx] = min(dp[i][curr_color_idx], dp[i-1][prev_color_idx])
                    else:
                        dp[i][curr_color_idx] = min(dp[i][curr_color_idx], dp[i-1][prev_color_idx] + 1)

    # Find minimum changes
    min_changes = min(dp[n-1])

    # Backtrack to find the sequence
    seq = [''] * n
    last_color_idx = dp[n-1].index(min_changes)
    seq[n-1] = ['R', 'G', 'B'][last_color_idx]

    for i in range(n-2, -1, -1):
        for curr_color_idx, curr_color in enumerate(['R', 'G', 'B']):
            if seq[i+1] != curr_color:
                if dp[i+1][curr_color_idx] == dp[i][curr_color_idx] + (0 if s[i] == curr_color else 1):
                    seq[i] = curr_color
                    break

    print(min_changes)
    print(''.join(seq))

solve()
